/** Skill files served over MCP, keyed by `<skill>/SKILL.md`. */
export const MCP_SKILL_FILES: Readonly<Record<string, string>> = {
  "catch-up/SKILL.md": "---\nname: catch-up\ndescription: Brief the user on one person before a meeting, a call, or a catch-up. Reads identity, recent interactions, important dates, relationships, groups, and tags. Read only.\n---\n\n# Catch up on someone\n\nBrief the user on one person before they meet, call, or message them.\n\n## Steps\n\n1. Ask for the name if the user did not give one. If the name is vague, ask for one more detail, for example the company or the city.\n2. Call `search_contacts` with the name.\n3. When several people match, list them by full name and company. Ask which person. Do not pick one.\n4. Call `get_contact` for the chosen `personId`.\n5. Call these in parallel with the same `personId`:\n   - `get_interactions` for recent history\n   - `get_important_dates`\n   - `get_relationships`\n   - `get_contact_groups`\n   - `get_contact_tags`\n6. Call `get_contact_linkedin` only when the user asks about work history, a role, a company, or education. Skip it for a short personal catch-up.\n\n## What to report\n\nWrite a short brief, not a data dump:\n\n- Who they are: name, role, company, city.\n- When you last spoke, and what you talked about.\n- Dates to remember: birthday, anniversary, or another date in the next 60 days.\n- Who else connects you: relationships and shared groups.\n- Two or three open threads the user can pick up.\n\nOrder the brief by what the user needs first. Keep it under 200 words unless the user asks for more.\n\n## Rules\n\n- Read only. Do not create, update, or delete anything in this skill.\n- Do not invent emails, phone numbers, jobs, or dates. Report only what a tool returned.\n- Say when a section is empty. \"No interactions saved\" is useful. Silence is not.\n\n## Failure lines\n\n- **Not connected:** if no Bondery tools are available, say the Bondery MCP server is not connected. Tell the user to add `https://api.usebondery.com/mcp` to their AI client and sign in.\n- **Signed out:** if a tool reports an authorization error, say the Bondery sign-in expired. Ask the user to reconnect the connector and sign in again.\n- **Read only when a write is needed:** this skill reads. If the user asks to change a record, say a write needs **Full access** and point to the `remember` skill.\n- **No match:** if `search_contacts` returns nothing, say you found no match. Ask for another spelling, a company, or a city. Do not create a contact from this skill.\n- **Cap:** collection tools return at most 25 rows. Say when a list stops at 25, and page with `offset` if the user wants more.\n- **Own card delete block:** `delete_contact` cannot delete the user's own card. This skill never deletes, so tell the user to use the Bondery app if they need that change.\n- **Wrong tool result:** if a tool returns a wrong or confusing result, call `create_agent_feedback` with the tool name, what you expected, what you got, and the `request_id`. Never include names, emails, notes, or phone numbers in the report.\n",
  "get-to-know/SKILL.md": "---\nname: get-to-know\ndescription: Deep research on one person before you meet them, using what Bondery holds. Covers what they do, what you have in common, and who you both know. Read only.\n---\n\n# Get to know someone\n\nBuild a profile of one person from what Bondery holds, so the user walks into the room prepared.\n\n## Steps\n\n1. Ask for the name if the user did not give one. Ask for a company or a city when the name is common.\n2. Call `search_contacts` with the name.\n3. When several people match, list them by full name and company. Ask which person. Do not pick one.\n4. Call `get_contact` for the chosen `personId`.\n5. Call these in parallel with the same `personId`:\n   - `get_contact_linkedin` for role, work history, and education\n   - `get_relationships` for who they know in the user's network\n   - `get_contact_groups` for shared context\n   - `get_contact_tags`\n   - `get_important_dates`\n   - `get_interactions` for history\n6. For each relationship the tools return, call `get_contact` on the related `personId` to name that person. Stop at the first 25 relationships.\n\n## What to report\n\nAnswer the three questions the user came with, in this order:\n\n1. **What they do.** Role, company, and the last two or three positions. Name the source when it is stored LinkedIn data rather than a note.\n2. **What you have in common.** Shared groups, shared tags, shared employers, shared schools, a shared city, and any relationship the tools return. Show the overlap on both sides. Do not claim a match you cannot support from a tool result.\n3. **Who you both know.** Name each related person and the relationship type. Say when the user has no stored relationship to that person.\n\nAdd one short section at the end: open threads the user can raise. Keep the whole answer under 300 words.\n\n## Rules\n\n- Read only. Never create, update, or delete anything in this skill.\n- Call `get_contact_linkedin` here because the job needs work history. Skip it only when the user asks for a personal read with no work angle.\n- Report only what a tool returned. Never fill a gap with a guess about a job, a school, or a person.\n- Say \"not stored\" when a field is empty. That answer helps the user decide what to add later.\n\n## Failure lines\n\n- **Not connected:** if no Bondery tools are available, say the Bondery MCP server is not connected. Tell the user to add `https://api.usebondery.com/mcp` to their AI client and sign in.\n- **Signed out:** if a tool reports an authorization error, say the Bondery sign-in expired. Ask the user to reconnect and sign in again.\n- **Read only when a write is needed:** this skill reads. If the user asks to update a record, say a write needs **Full access** and point to the `remember` skill.\n- **No match:** if `search_contacts` returns nothing, say you found no match. Offer the `remember` skill to save the person first, and say that needs **Full access**.\n- **Cap:** relationship lists and collections return at most 25 rows. Say when a list is capped.\n- **Own card delete block:** `delete_contact` cannot delete the user's own card. This skill never deletes.\n- **Wrong tool result:** if a tool returns a wrong or confusing result, call `create_agent_feedback` with the tool name, what you expected, what you got, and the `request_id`. Never include names, emails, notes, or phone numbers in the report.\n",
  "onboarding/SKILL.md": "---\nname: onboarding\ndescription: Introduce Bondery and the skills a person can use. Run after install, and when the user asks what Bondery is or what it can do.\n---\n\n# Welcome to Bondery\n\nTell the user what Bondery is, then name the skills they can use. Do not call tools in this skill.\n\n## What to say\n\nBondery is a personal relationship manager (PRM). It keeps the people they know, what they talked about, and when they last reached out. It is a quiet place for that, not a sales pipeline.\n\nName these skills and the one job each does:\n\n- `catch-up` briefs one person before a meeting, a call, or a message.\n- `get-to-know` covers what someone does, what you have in common, and who you both know.\n- `remember` saves a person or a conversation.\n- `reach-out` shows who to contact, from overdue keep-in-touch and upcoming dates.\n- `share-person` emails a contact card after the user confirms the recipients and the fields.\n\nSay that catch up, get to know, and reach out only read. Remember and share write, and they need **Full access**.\n\nAsk which job they want. When they do not pick one, offer a brief before a meeting.\n\n## Rules\n\n- Do not invent people, emails, phone numbers, or dates in this introduction.\n- Do not mention what Bondery costs.\n- Do not paste the privacy policy or the terms. When the user asks how data is handled, point to https://usebondery.com/privacy and https://usebondery.com/terms.\n\n## Failure lines\n\n- **Not connected:** if no Bondery tools are available, say the Bondery MCP server is not connected. Tell the user to add `https://api.usebondery.com/mcp` to their AI client and sign in.\n- **Signed out:** if a tool reports an authorization error, say the Bondery sign-in expired. Ask the user to reconnect the connector and sign in again.\n",
  "reach-out/SKILL.md": "---\nname: reach-out\ndescription: Show who to contact this week. Lists overdue keep-in-touch contacts and upcoming important-date reminders as two separate lists. Read only.\n---\n\n# Who to reach out to\n\nAnswer \"who should I contact\" with two clean lists. Do not mix them.\n\n## Steps\n\n1. Call `get_keep_in_touch_count` to get the overdue total.\n2. Call `get_keep_in_touch_contacts` for the people with a keep-in-touch cadence.\n3. Call `get_upcoming_reminders` for dates with notifications in the next month.\n4. When the user wants one person in more detail, run the `catch-up` skill for that person.\n\n## What to report\n\nKeep two lists. Give each list its own heading, and never merge them.\n\n- **Overdue keep-in-touch.** Each row: full name, cadence in days, and the last interaction date.\n- **Dates coming up.** Each row: full name, the date, and how many days away.\n\nPut the overdue total above the first list, taken from `get_keep_in_touch_count`. Each list stops at 25 rows. Say when it does.\n\nWhen both lists are empty, say nobody is due this week. Do not pad the answer.\n\n## Rules\n\n- Read only. Do not create or update a cadence from this skill. Use `remember` or the Bondery app when the user wants to change one.\n- Do not rank people by guessed importance. Order each list by the date the tool returns.\n- Cadence is a nudge rhythm, not a message. Do not draft or send a message here.\n\n## Failure lines\n\n- **Not connected:** if no Bondery tools are available, say the Bondery MCP server is not connected. Tell the user to add `https://api.usebondery.com/mcp` to their AI client and sign in.\n- **Signed out:** if a tool reports an authorization error, say the Bondery sign-in expired. Ask the user to reconnect and sign in again.\n- **Read only when a write is needed:** this skill reads. If the user asks to change a cadence, say a write needs **Full access** and the `remember` skill.\n- **Nobody due:** when both lists are empty, say nobody is due this week. Suggest checking again next week or lowering a cadence in the app.\n- **Cap:** each list stops at 25 rows. Say when a list is capped, and page with `offset` when the user wants the rest.\n- **Own card delete block:** `delete_contact` cannot delete the user's own card. This skill never deletes.\n- **Wrong tool result:** if a tool returns a wrong or confusing result, call `create_agent_feedback` with the tool name, what you expected, what you got, and the `request_id`. Never include names, emails, notes, or phone numbers in the report.\n",
  "remember/SKILL.md": "---\nname: remember\ndescription: Save a person, a conversation, or a note in Bondery. Searches first so a duplicate never lands. Replaces important dates as a whole list. Needs Full access.\n---\n\n# Remember someone or something\n\nSave a new person or a conversation the user just had.\n\n## Steps\n\n### A new person\n\n1. Call `search_contacts` with the name before anything else.\n2. When one person already matches, do not create a second card. Offer `update_contact` instead, and say why.\n3. When several people match, list them by full name and company. Ask which person. Do not pick one.\n4. When nobody matches, call `create_contact` with only the fields the user gave: name, and optionally emails, phones, socials, notes, location, and keep-in-touch cadence.\n\n### A conversation\n\n1. Find the people first with `search_contacts`. Search each participant.\n2. Call `create_interaction` with `participantIds`, the date, the type, and the note. `participantIds` accepts at most 25 people.\n3. When a participant already has no card, ask the user whether to create the contact first. Do not guess.\n\n### A note or a new date\n\n1. Use `update_contact` to change notes, channels, socials, language, timezone, or location. Send `[]` to clear a channel list.\n2. Before `update_important_dates`, call `get_important_dates` and read the current list.\n3. Send the full list back with the new entry. The tool replaces every date, so a partial list deletes the rest.\n\n## Rules\n\n- Full access is required for every write. When the user approved **Read only**, say so and stop. Ask them to reconnect with **Full access**.\n- Search first, always. Never create a duplicate person.\n- Ask before a delete. Deletes need a host confirmation, and some clients cannot confirm.\n- Do not invent a date, an email, or a phone number. Save only what the user said.\n\n## Failure lines\n\n- **Not connected:** if no Bondery tools are available, say the Bondery MCP server is not connected. Tell the user to add `https://api.usebondery.com/mcp` to their AI client and sign in.\n- **Signed out:** if a tool reports an authorization error, say the Bondery sign-in expired. Ask the user to reconnect and sign in again.\n- **Read only when a write is needed:** if a write fails with a permission error, say the connector has **Read only** access. The user must reconnect with **Full access**.\n- **Confirm before delete:** never delete a person, an interaction, a group, a tag, or a relationship without an explicit yes from the user in this conversation.\n- **No match:** if a search returns nothing, say you found no match. Then ask whether to create the person.\n- **Cap:** collection tools return at most 25 rows. `create_interaction` accepts at most 25 participants. `delete_tags` takes at most 25 tags. Split a longer list into batches, and tell the user when you do.\n- **Own card delete block:** `delete_contact` cannot delete the user's own card. Say the own card stays, and point to the Bondery app.\n- **Wrong tool result:** if a tool returns a wrong or confusing result, call `create_agent_feedback` with the tool name, what you expected, what you got, and the `request_id`. Never include names, emails, notes, or phone numbers in the report.\n",
  "share-person/SKILL.md": "---\nname: share-person\ndescription: Email a contact card to one or more people. Previews the fields first and waits for the user to confirm the recipients and fields. Needs Full access.\n---\n\n# Share a person\n\nEmail a contact card to a colleague, a recruiter, or a friend. The user picks the recipients and the fields.\n\n## Steps\n\n1. Find the person with `search_contacts`.\n2. When several people match, list them by full name and company. Ask which person. Do not pick one.\n3. Call `get_contact_share` with the chosen `personId`. It returns `contactName` and `availableFields`.\n4. Show `contactName` and every available field to the user. Ask two questions:\n   - Which email addresses receive the card? At most 10.\n   - Which fields go in the card?\n5. Read the answer back in one short message: contact name, recipients, and selected fields. Ask for an explicit yes.\n6. After the yes, call `create_contact_share` with `personId`, `recipientEmails`, and `selectedFields`. Add `message` when the user gave one.\n7. Report the result. Say the email cannot be undone.\n\n## Rules\n\n- Full access is required. When the user approved **Read only**, say so and stop.\n- Never send a share email without an explicit yes in this conversation. The host also asks for a confirmation. Do not skip either step.\n- Send only the fields the user chose. Do not add a field to make the card look better.\n- Accept at most 10 recipients. Ask the user to split a longer list.\n- Do not guess an email address. Ask for the full address.\n\n## Failure lines\n\n- **Not connected:** if no Bondery tools are available, say the Bondery MCP server is not connected. Tell the user to add `https://api.usebondery.com/mcp` to their AI client and sign in.\n- **Signed out:** if a tool reports an authorization error, say the Bondery sign-in expired. Ask the user to reconnect and sign in again.\n- **Read only when a write is needed:** if the share fails with a permission error, say the connector has **Read only** access. The user must reconnect with **Full access**.\n- **Confirm before a share email:** never send with a guessed or implied yes. Outbound email cannot be undone.\n- **No match:** if `search_contacts` returns nothing, say you found no match. Ask for another spelling or a company. Do not create a new contact from this skill.\n- **Cap:** a share email accepts at most 10 recipients. Say when the list is longer.\n- **Own card delete block:** `delete_contact` cannot delete the user's own card. This skill never deletes.\n- **Wrong tool result:** if a tool returns a wrong or confusing result, call `create_agent_feedback` with the tool name, what you expected, what you got, and the `request_id`. Never include names, emails, notes, or phone numbers in the report.\n",
};
